#!/bin/sh
# DSM package lifecycle for Homeward.
#
# The scripts preinst, postinst, preuninst, postuninst, preupgrade, postupgrade
# and start-stop-status are generated by tools/build_spk.py; each one sources
# this file and calls the matching function. DSM 7 runs all of them as the
# unprivileged package user "sc-homeward" (conf/privilege).
#
# Layout on the NAS:
#   /var/packages/homeward/target/wheelhouse  bundled wheels (replaced on upgrade)
#   /var/packages/homeward/target/env         venv built from them in postinst
#   /var/packages/homeward/var                config, state, status, log (kept on upgrade)
#   /var/packages/homeward/shares/homeward    the package's own shared folder

PKG_NAME="${SYNOPKG_PKGNAME:-homeward}"
PKG_DEST="${SYNOPKG_PKGDEST:-/var/packages/${PKG_NAME}/target}"
PKG_VAR="${SYNOPKG_PKGVAR:-/var/packages/${PKG_NAME}/var}"
PKG_SHARE="${HOMEWARD_SHARE:-/var/packages/${PKG_NAME}/shares/homeward}"
PYTHON="${HOMEWARD_PYTHON:-/var/packages/python312/target/bin/python3.12}"

VENV="${PKG_DEST}/env"
WHEELHOUSE="${PKG_DEST}/wheelhouse"
CONFIG="${PKG_VAR}/config.toml"
PID_FILE="${PKG_VAR}/homeward.pid"
LOG_FILE="${PKG_VAR}/homeward.log"
LOG_MAX_BYTES=5242880
STOP_TIMEOUT=45

# Messages for the user. DSM shows the content of SYNOPKG_TEMP_LOGFILE in Package
# Center when a script exits non-zero.
fail() {
    echo "$1"
    if [ -n "${SYNOPKG_TEMP_LOGFILE}" ]; then
        echo "$1" >> "${SYNOPKG_TEMP_LOGFILE}"
    fi
    exit 1
}

service_preinst() {
    if [ ! -x "${PYTHON}" ]; then
        fail "Python 3.12 from SynoCommunity is missing (${PYTHON}). Please install the package \"Python 3.12\" first."
    fi
}

service_postinst() {
    echo "Creating the Python environment in ${VENV}"
    rm -rf "${VENV}"
    "${PYTHON}" -m venv "${VENV}" || fail "Could not create the Python environment in ${VENV}."
    PIP_DISABLE_PIP_VERSION_CHECK=1 "${VENV}/bin/pip" install --quiet --no-index --no-cache-dir \
        --find-links "${WHEELHOUSE}" "homeward[icloud]" \
        || fail "Could not install Homeward into ${VENV}."

    mkdir -p "${PKG_VAR}/state"
    if [ ! -f "${CONFIG}" ]; then
        echo "Writing the default configuration to ${CONFIG}"
        cat > "${CONFIG}" <<CONF
# Homeward configuration. Sync pairs are added here (later through the DSM UI).
# See docs/architecture.md for all options.
state_dir = "state"

[daemon]
interval_minutes = 60

# [[pair]]
# name = "docs"
# local = "${PKG_SHARE}/Documents"
# remote = "Documents"
# mode = "upload"
CONF
    fi
}

service_preupgrade() {
    :
}

service_postupgrade() {
    HOMEWARD_VAR="${PKG_VAR}" HOMEWARD_CONFIG="${CONFIG}" "${VENV}/bin/python" -m homeward.api.migrate \
        || echo "Could not update ${CONFIG}; check it in the Homeward app."
    return 0
}

service_preuninst() {
    # Upgrades also run the uninstall scripts; only a real uninstall removes var/.
    if [ "${SYNOPKG_PKG_STATUS}" = "UPGRADE" ]; then
        return 0
    fi
    backup_var
}

service_postuninst() {
    :
}

# Copy config and state into the package's share before DSM deletes var/, so a
# reinstall can pick them up again. The synced files themselves live in shares
# and are never touched by an uninstall. The iCloud sessions (trusted-session
# cookies) stay behind: anyone who can read the share could use them to reach the
# Apple ID, so a reinstall asks to sign in again instead.
backup_var() {
    if [ ! -d "${PKG_SHARE}" ] || [ ! -f "${CONFIG}" ]; then
        return 0
    fi
    dest="${PKG_SHARE}/.homeward-backup/$(date +%Y-%m-%d_%H%M%S)"
    echo "Saving configuration and state (without the iCloud sessions) to ${dest}"
    mkdir -p "${dest}" && cp -p "${CONFIG}" "${dest}/" || return 0
    if [ -d "${PKG_VAR}/state" ]; then
        mkdir -p "${dest}/state"
        for entry in "${PKG_VAR}/state"/* "${PKG_VAR}/state"/.[!.]*; do
            [ -e "${entry}" ] || continue
            case "$(basename "${entry}")" in
                sessions | sessions-pending) continue ;;
            esac
            cp -pR "${entry}" "${dest}/state/"
        done
    fi
}

daemon_running() {
    [ -r "${PID_FILE}" ] && kill -0 "$(cat "${PID_FILE}")" 2>/dev/null
}

rotate_log() {
    if [ -f "${LOG_FILE}" ] && [ "$(wc -c < "${LOG_FILE}")" -gt "${LOG_MAX_BYTES}" ]; then
        mv -f "${LOG_FILE}" "${LOG_FILE}.1"
    fi
}

service_start() {
    if daemon_running; then
        return 0
    fi
    rotate_log
    # HOME points into var/ so libraries that write to ~ (cookies, caches) stay
    # inside the package and survive upgrades.
    HOME="${PKG_VAR}" HOMEWARD_CONFIG="${CONFIG}" \
        nohup "${VENV}/bin/homeward-daemon" --config "${CONFIG}" >> "${LOG_FILE}" 2>&1 &
    echo $! > "${PID_FILE}"
    sleep 1
    daemon_running || { rm -f "${PID_FILE}"; fail "Homeward did not start, see ${LOG_FILE}."; }
}

service_stop() {
    if ! daemon_running; then
        rm -f "${PID_FILE}"
        return 0
    fi
    pid="$(cat "${PID_FILE}")"
    kill -TERM "${pid}"
    i=0
    while kill -0 "${pid}" 2>/dev/null; do
        i=$((i + 1))
        if [ "${i}" -ge "${STOP_TIMEOUT}" ]; then
            kill -KILL "${pid}" 2>/dev/null
            break
        fi
        sleep 1
    done
    rm -f "${PID_FILE}"
}

service_start_stop_status() {
    case "$1" in
        start) service_start ;;
        stop) service_stop ;;
        status) daemon_running && exit 0 || exit 3 ;;
        log) echo "${LOG_FILE}" ;;
        *) echo "usage: $0 start|stop|status|log"; exit 1 ;;
    esac
}
